class.description:
Extend this class to define how a path prefix such as [code]mods://[/code] is turned into a real path on the current platform, and back. Register an instance with [method PathPrefixServer.register_prefix].
The methods can be called from any thread, for example from [ResourceLoader] threads. They must be thread-safe and must not touch the scene tree.
[codeblocks]
[gdscript]
class_name ModsPrefix
extends PathPrefix

func _globalize(path: String) -> String:
	return OS.get_executable_path().get_base_dir().path_join("mods").path_join(path.trim_prefix("mods://"))
[/gdscript]
[csharp]
using Godot;

public partial class ModsPrefix : PathPrefix
{
    public override string _Globalize(string path)
    {
        return OS.GetExecutablePath().GetBaseDir().PathJoin("mods").PathJoin(path.TrimPrefix("mods://"));
    }
}
[/csharp]
[/codeblocks]
